const body = $input.first().json.body || {};
const missing = ['company_name','competitors','product_context'].filter(f => !body[f] || String(body[f]).trim() === '');
if (missing.length > 0) return [{ json: { _valid: false, _error: 'Missing required fields: ' + missing.join(', ') } }];
return [{ json: { ...body, _valid: true } }];

const d = $input.first().json;
const raw = d.competitors;
const list = Array.isArray(raw) ? raw : String(raw).split(',').map(c => c.trim()).filter(Boolean);
const tiered = list.map((name, i) => ({ name, threat_tier: i < 2 ? 'primary' : i < 4 ? 'secondary' : 'peripheral' }));
return [{ json: {
  company_name: d.company_name,
  product_context: d.product_context,
  industry: d.industry || 'not specified',
  run_type: d.run_type || 'deep_dive',
  competitors: tiered,
  competitors_json: JSON.stringify(tiered)
} }];

