const raw = $input.first().json.choices[0].message.content;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!parsed.competitors || !Array.isArray(parsed.competitors)) throw new Error('Positioning Agent: invalid schema — missing competitors array');
return [{ json: { positioning_output: parsed.competitors } }];

const raw = $input.first().json.choices[0].message.content;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!parsed.narratives || !Array.isArray(parsed.narratives)) throw new Error('Narrative Agent: invalid schema — missing narratives array');
return [{ json: { narrative_output: parsed.narratives } }];

const merged = $input.first().json;
return [{ json: {
  _e: 0,
  generation_run_id: $execution.id,
  run_type: $('Market Context Contextualizer').first().json.run_type,
  company_name: $('Market Context Contextualizer').first().json.company_name,
  positioning_output: merged.positioning_output || null,
  narrative_output: merged.narrative_output || null
} }];
